{
  "image": "rhino-ai-agent-sandbox-v1-release-<timestamp>",
  "fcp_mirror_sha": "<commit the mirror was at>",
  "lockfiles": {
    "frontend/package-lock.json": "sha256:<hash>",
    "cloud/uv.lock": "sha256:<hash>",
    "client/uv.lock": "sha256:<hash>"
  },
  "fcp_lab": "<pinned tag>",
  "claude_code": "<pinned version>",
  "harness": "<ai-agents release>"
}

packer {
  required_plugins {
    amazon  = { source = "github.com/hashicorp/amazon", version = "~> 1" }
    ansible = { source = "github.com/hashicorp/ansible", version = "~> 1" }
  }
}

source "amazon-ebs" "image" {
  region        = var.region
  instance_type = var.instance_type
  ami_name      = "rhino-${var.image}-v${var.version}-${var.channel}-${local.timestamp}"
  ssh_username  = "ubuntu"
  source_ami_filter {
    filters     = { name = var.source_ami_name }
    owners      = [var.source_ami_owner]
    most_recent = true
  }
}

build {
  sources = ["source.amazon-ebs.image"]
  provisioner "ansible" {
    playbook_file = "${path.root}/../images/${var.image}/playbook.yml"
  }
}
